func (f *Forwarder) getOrCreateCredential(ctx authContext) (*tls.Config, error) {
	if config := f.getCredential(ctx); config != nil {
		return config, nil
	}
	requestCtx, done := f.getOrCreateRequestContext(ctx.key())
	if done != nil {
		defer done()
		// Another request may have populated the cache before we acquired the lock.
		if config := f.getCredential(ctx); config != nil {
			return config, nil
		}
		config, err := f.requestCertificate(ctx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		cert := config.Certificates[0].Leaf
		if cert == nil || !cert.NotAfter.After(f.Clock.Now().Add(time.Minute)) {
			return nil, trace.BadParameter("Kubernetes certificate expires too soon")
		}
		f.Lock()
		err = f.credentials.Set(ctx.key(), config, cert.NotAfter.Sub(f.Clock.Now().Add(time.Minute)))
		f.Unlock()
		return config, trace.Wrap(err)
	}
	select {
	case <-requestCtx.Done():
		if config := f.getCredential(ctx); config != nil {
			return config, nil
		}
		return nil, trace.BadParameter("failed to request certificate, try again")
	case <-f.ctx.Done():
		return nil, trace.BadParameter("forwarder is closing, aborting the request")
	}
}

