// getCredential returns a cached certificate only while it has at least one
// minute of validity remaining.
func (f *Forwarder) getCredential(ctx authContext) *tls.Config {
	f.Lock()
	defer f.Unlock()
	cached, ok := f.credentials.Get(ctx.key())
	if !ok {
		return nil
	}
	config := cached.(*tls.Config)
	if len(config.Certificates) == 0 || config.Certificates[0].Leaf == nil ||
		config.Certificates[0].Leaf.NotAfter.Before(f.Clock.Now().Add(time.Minute)) {
		f.credentials.Remove(ctx.key())
		return nil
	}
	return config
}

